style.css:
@-moz-document domain("wikipedia.org") {
/* 1. Hide the original logo image (the globe SVG) */
    .mw-wiki-logo {
        display: none !important;
        visibility: hidden !important;
        background-image: none !important;
    }
    
    /* 2. Hide the original logo text (the "WIKIPEDIA" below the globe) */
    .mw-logo-wordmark {
        display: none !important;
        visibility: hidden !important;
    }
    
    /* 3. Target the main logo container and apply the custom image */
    #p-logo, .mw-logo-container {
        /* Set custom dimensions (Wikipedia logo is usually about 140px wide) */
        width: 140px !important; 
        height: 160px !important;
        
        /* Your custom image link */
        background-image: url("https://i.imgur.com/TEx9NUN.png") !important; 
        
        /* Ensure the container is visible */
        display: block !important;
        
        /* Image display settings */
        background-repeat: no-repeat !important;
        background-position: center top !important; 
        background-size: contain !important; 
        
        /* Add margin to move it down slightly if needed */
        margin-top: 5px !important;
    }
}
